		if(Main.mobile) {
			let words = line.split(" ");
			let row = "";
			let y = Main.footerY + 49;
			let count = 0;
			Main.ctx.font = "14px " + Main.sans;
			let _g = 0;
			while(_g < words.length) {
				let word = words[_g];
				++_g;
				if(Main.ctx.measureText(row + " " + word).width > Main.sw - 40 && row != "") {
					Main.text(row,Main.left + 20,y,14,Main.white);
					y += 19;
					++count;
					row = "";
					if(count >= 3) {
						break;
					}
				}
				row += (row == "" ? "" : " ") + word;
			}
			if(count < 3 && row != "") {
				Main.text(row,Main.left + 20,y,14,Main.white);
			}
		} else {
			Main.fit(line,Main.left + 20,Main.footerY + 49,Main.W - Main.pad * 2 - 180,14,Main.white);
		}
